content.css:
.rcs-root {
  width: 100%;
  height: 100%;
  position: relative;
  box-sizing: border-box;
  padding-bottom: 24px;
  background: #FFFFFF;
  color: #242424;
  font-family: "Segoe UI", system-ui, sans-serif;
}
.rcs-chart,
.rcs-landing {
  width: 100%;
  height: 100%;
}
.rcs-landing {
  display: none;
}
.rcs-shell {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  box-sizing: border-box;
}
.rcs-header {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px 4px;
  border-bottom: 1px solid #E5E7EB;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
}
.rcs-header__titles {
  flex: 1;
  min-width: 0;
}
.rcs-header__title {
  font-weight: 600;
  color: #242424;
  line-height: 1.2;
}
.rcs-header__subtitle {
  color: #6C757D;
  line-height: 1.2;
  margin-top: 2px;
}
.rcs-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E5E7EB;
  background: #FFFFFF;
  color: #6C757D;
  font: italic 600 12px/18px "Georgia", serif;
  cursor: pointer;
  padding: 0;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.rcs-header__info:hover {
  background: #E8612A;
  color: #fff;
  border-color: #E8612A;
}
.rcs-header__info-pop {
  position: absolute;
  top: 36px;
  right: 12px;
  z-index: 30;
  width: 320px;
  max-width: calc(100% - 24px);
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 6px;
  box-shadow: 0 6px 24px rgba(15, 23, 42, 0.12);
  padding: 14px 16px 12px;
  font-size: 12px;
  color: #242424;
}
.rcs-header__info-pop[hidden] {
  display: none;
}
.rcs-header__info-close {
  position: absolute;
  top: 6px;
  right: 8px;
  width: 18px;
  height: 18px;
  border: 0;
  background: transparent;
  cursor: pointer;
  color: #6C757D;
  font-size: 16px;
  line-height: 1;
}
.rcs-header__info-close:hover {
  color: #E8612A;
}
.rcs-header__info-title {
  font-weight: 600;
  font-size: 13px;
  padding-bottom: 6px;
  border-bottom: 2px solid #E8612A;
  margin-bottom: 8px;
}
.rcs-header__info-desc {
  line-height: 1.45;
  margin-bottom: 8px;
}
.rcs-header__info-howto {
  font-weight: 600;
  color: #6C757D;
  margin: 6px 0 4px;
  text-transform: uppercase;
  font-size: 11px;
  letter-spacing: 0.04em;
}
.rcs-header__info-bullets {
  margin: 0;
  padding-left: 18px;
  line-height: 1.5;
}
.rcs-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: row;
  position: relative;
}
.rcs-body .rcs-canvas {
  flex: 1;
  min-width: 0;
  min-height: 0;
  position: relative;
  padding: 6px 4px 0 6px;
  box-sizing: border-box;
}
.rcs-body .rcs-svg {
  display: block;
  width: 100%;
  height: 100%;
}
.rcs-body .rcs-insight-strip {
  flex: 0 0 24px;
  background: #F8F9FB;
  border-left: 1px solid #E5E7EB;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  user-select: none;
}
.rcs-body .rcs-insight-strip__arrow {
  color: var(--rcs-insight-accent, #E8612A);
  font-size: 14px;
  line-height: 1;
}
.rcs-body .rcs-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: 10px;
  letter-spacing: 0.14em;
  color: #6C757D;
  font-weight: 600;
}
.rcs-body .rcs-insight-strip:hover {
  background: #fbe3d9;
}
.rcs-body .rcs-insight-panel {
  flex: 0 0 250px;
  max-width: 320px;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  border-left: 1px solid #E5E7EB;
  padding: 10px 12px 14px;
  box-sizing: border-box;
  overflow-y: auto;
  --rcs-insight-font: 11px;
  --rcs-insight-header-font: 12px;
  --rcs-insight-accent: #E8612A;
  font-size: var(--rcs-insight-font);
  color: #242424;
}
.rcs-body--insight-expanded .rcs-insight-panel {
  display: block;
}
.rcs-body--insight-collapsed .rcs-insight-panel {
  display: none;
}
.rcs-body--insight-hidden .rcs-insight-strip,
.rcs-body--insight-hidden .rcs-insight-panel {
  display: none;
}
.rcs-insight-header {
  margin-bottom: 10px;
  padding-bottom: 6px;
  border-bottom: 2px solid var(--rcs-insight-accent);
}
.rcs-insight-header__title {
  font-size: var(--rcs-insight-header-font);
  font-weight: 700;
  color: #242424;
  line-height: 1.2;
}
.rcs-insight-header__count {
  font-size: calc(var(--rcs-insight-font) - 1px);
  color: #6C757D;
  margin-top: 2px;
}
.rcs-insight-kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 12px;
}
.rcs-kpi {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-left: 3px solid #E8612A;
  padding: 6px 8px;
  border-radius: 3px;
}
.rcs-kpi__value {
  font-weight: 700;
  font-size: calc(var(--rcs-insight-font) + 3px);
  color: #242424;
  line-height: 1.1;
}
.rcs-kpi__label {
  font-size: calc(var(--rcs-insight-font) - 1px);
  color: #6C757D;
  margin-top: 2px;
}
.rcs-insight-health {
  margin-bottom: 12px;
}
.rcs-insight-health__label {
  font-size: calc(var(--rcs-insight-font) - 1px);
  color: #6C757D;
  margin-bottom: 4px;
}
.rcs-insight-health__bar {
  height: 8px;
  background: #E5E7EB;
  border-radius: 4px;
  overflow: hidden;
}
.rcs-insight-health__fill {
  height: 100%;
  transition: width 0.3s ease;
}
.rcs-insight-health__value {
  font-size: calc(var(--rcs-insight-font) - 1px);
  color: #242424;
  margin-top: 3px;
  text-align: right;
  font-weight: 600;
}
.rcs-insight-smart__title,
.rcs-insight-list__title {
  font-weight: 600;
  color: #6C757D;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: calc(var(--rcs-insight-font) - 1px);
  margin: 6px 0 4px;
}
.rcs-insight-smart {
  margin: 0 0 10px;
  padding-left: 16px;
}
.rcs-insight-smart li {
  margin-bottom: 4px;
  line-height: 1.4;
}
.rcs-insight-smart b {
  color: #242424;
}
.rcs-insight-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.rcs-insight-list li {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 0;
  border-bottom: 1px dashed #E5E7EB;
  font-size: var(--rcs-insight-font);
}
.rcs-insight-list li:last-child {
  border-bottom: 0;
}
.rcs-insight-list .rcs-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: 0 0 8px;
}
.rcs-insight-list .rcs-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.rcs-insight-list .rcs-val {
  color: #6C757D;
  font-variant-numeric: tabular-nums;
}
.rcs-insight-narrative {
  margin: 4px 0 8px;
  padding: 8px 10px;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-left: 3px solid var(--rcs-insight-accent, #E8612A);
  border-radius: 3px;
  font-size: var(--rcs-insight-font);
  line-height: 1.45;
  color: #242424;
}
.rcs-insight-narrative b {
  font-weight: 700;
}
.rcs-insight-narrative i {
  color: #6C757D;
}
.rcs-insight-btn {
  margin-top: 6px;
  padding: 5px 10px;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 3px;
  color: #242424;
  font-size: calc(var(--rcs-insight-font) - 1px);
  cursor: pointer;
  width: 100%;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.rcs-insight-btn:hover {
  background: #F8F9FB;
  border-color: var(--rcs-insight-accent, #E8612A);
}
.rcs-insight-btn--primary {
  background: var(--rcs-insight-accent, #E8612A);
  color: #fff;
  border-color: var(--rcs-insight-accent, #E8612A);
}
.rcs-insight-btn--primary:hover {
  background: #dc5018;
  color: #fff;
}
.rcs-grid line {
  shape-rendering: crispEdges;
}
.rcs-insight-legend {
  margin: 0 0 10px;
  padding: 0;
  list-style: none;
}
.rcs-insight-legend li {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 4px 0;
  font-size: calc(var(--rcs-insight-font) - 1px);
  line-height: 1.4;
  color: #6C757D;
  border-bottom: 1px dashed #E5E7EB;
}
.rcs-insight-legend li:last-child {
  border-bottom: 0;
}
.rcs-insight-legend li b {
  color: #242424;
  font-weight: 600;
}
.rcs-insight-legend .rcs-dot {
  width: 9px;
  height: 9px;
  border-radius: 2px;
  flex: 0 0 9px;
  margin-top: 3px;
}
.rcs-label,
.rcs-bar-label {
  font-family: inherit;
}
.rcs-x-axis path,
.rcs-y-axis path,
.rcs-x-axis line,
.rcs-y-axis line {
  stroke: #E5E7EB;
}
.rcs-legend text {
  dominant-baseline: middle;
}
.rcs-chart.rcs-medium .rcs-body .rcs-insight-panel {
  flex-basis: 200px;
}
.rcs-chart.rcs-narrow .rcs-body .rcs-insight-panel {
  position: absolute;
  right: 24px;
  top: 0;
  bottom: 0;
  width: 220px;
  z-index: 5;
  box-shadow: -4px 0 12px rgba(15, 23, 42, 0.08);
}
.bfusion-landing {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  width: 100%;
  height: 100%;
  padding: 24px;
  box-sizing: border-box;
  background: #F8F9FB;
  font-family: "Segoe UI", system-ui, sans-serif;
  color: #242424;
}
.bfusion-landing__logo-container {
  flex: 0 0 auto;
}
.bfusion-landing__logo {
  width: 96px;
  height: auto;
  border-radius: 12px;
}
.bfusion-landing__text-container {
  max-width: 460px;
}
.bfusion-landing__title {
  margin: 0 0 6px;
  color: #1F2A44;
  font-size: 18px;
}
.bfusion-landing__description {
  margin: 0 0 12px;
  line-height: 1.5;
  color: #242424;
  font-size: 13px;
}
.bfusion-landing__separator {
  height: 1px;
  background: #E5E7EB;
  margin: 8px 0;
}
.bfusion-landing__metadata {
  font-size: 12px;
  color: #6C757D;
  line-height: 1.6;
}
.bfusion-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  background: #F8F9FB;
}
.bfusion-empty__message {
  color: #6C757D;
  font-size: 13px;
  font-style: italic;
}
